#!/usr/bin/env bash
# Ms. Codex 860 - [Collection of documents concerning inheritance] (UPenn), 91 images, full/max JPEGs
# Note: fols. 41v-46r are blank and were not photographed (per the manifest).
set -u
OUT="${1:-MsCodex860}"; mkdir -p "$OUT"
dl() { local f="$OUT/$1.jpg"; [ -s "$f" ] && return; curl -fsS --retry 5 --retry-delay 5 -o "$f.part" "$2" && mv "$f.part" "$f" && echo "ok  $1" || echo "FAIL $1"; sleep 1; }
